// Series data — Value.
// Generated by generate.js from results.csv: task "value"
// (star_to, ascii8, sensitive), budget 2^48 per search. One record
// per edge; its steps are every successively longer prefix match (first
// counter value per match length) of the one continuing grind. Every
// candidate message is base ‖ counter (64-bit little-endian; the counter is
// the "nonce" column in results.csv); every hash below was re-verified as
// SHA-256(base ‖ counter) at generation time.
(function () {
  const grinding = window.grinding = window.grinding || {};

  // base, word, matched chars, counter (the csv’s nonce), hash
  const rows = [
    ["use", "art", 1, 773, "6113b3721e77992512a76d70cf986202b605017c8e3da0d3add675d88edf7ae6"],
    ["use", "art", 2, 69685, "61728a17ca33dee14b6f2c32e4a94ef183774363e641be2062221ab0cf9fa25a"],
    ["use", "art", 3, 25861510, "617274b0a647ad247a2ab9e2e7ba07221310535d95a1af440fb6ae731344725a"],
    ["utility", "art", 1, 98, "619bc5b1757e8f64d477ac05c06310811994071dc5272a8b5be419500e9a3510"],
    ["utility", "art", 2, 41087, "6172532eaa9dc89e12bb9fc7b3556f323621eae443bd074dd211b2d272cbf3af"],
    ["utility", "art", 3, 31076760, "617274aa6ffc1841fffa35d960db59232b8194f513202a06cd5e8101d4269c04"],
    ["aura", "art", 1, 464, "61c090df8b7a42a2841fdb70a34910461c39fc06723793f702d0f8b2bd92475c"],
    ["aura", "art", 2, 17503, "6172bf9f37f44fcb10c78acff5d78cce39f4757bdf0c00977e6cba730b59983f"],
    ["aura", "art", 3, 25361818, "6172749981e2060b43834d4bade480037aaf91c421a72aeb976cc7b455bb33b5"],
    ["price", "art", 1, 634, "617040fc135c50293f1f6572b258e38c6bfbf3f0f7c20da9988a202271a6646a"],
    ["price", "art", 2, 49526, "6172be05283b95ae58620c2d8fd50e79adc3d696667516ea8fb4df896ccca065"],
    ["price", "art", 3, 11993061, "6172745c2ffa1eb8524e2c58ab1a6019a0551f5eddba71b06043aae6a992913a"],
    ["worth", "art", 1, 21, "611d1529bbf0717c94cf829e1816ef1399a87ae16f99d886f4016fbe09ca3af5"],
    ["worth", "art", 2, 106008, "617269d1219750f7950d254e894576c3771af90569e19834c0d2bac7672f4e05"],
    ["worth", "art", 3, 34401253, "6172747409572495a5dff4487d34fca15ee614785e6367d84740316626395435"],
  ];

  const ascii8hex = s => [...s].map(c => c.charCodeAt(0).toString(16).padStart(2, "0")).join("");
  const edges = [];
  for (const [base, word] of rows)
    if (!edges.some(e => e[0] === base && e[1] === word)) edges.push([base, word]);

  grinding.series = {
    name: "Value",
    slug: "value",
    base: "",
    topology: "star_to",
    searchEncoding: "ascii8",
    caseMode: "sensitive",
    hashFunction: "SHA-256",
    budgetBits: 48,
    tokenId: 8, // position in the fixed edition; scripts/tokens.js agrees
    records: edges.map(([base, word], index) => {
      let prevNonce = 0;
      const steps = rows.filter(r => r[0] === base && r[1] === word)
        .map(([, , matchedChars, nonce, hash]) => {
          const st = { matchedChars, nonce, prevNonce, deltaAttempts: nonce - prevNonce, hash };
          prevNonce = nonce;
          return st;
        });
      const final = steps[steps.length - 1];
      return {
        index,
        word,
        base,
        labelPrefix: base + " \u2192\u00a0", // nbsp: a plain trailing space collapses in SVG
        plaintext: word, // as it appears in the csv
        totalChars: word.length,
        matchedChars: final.matchedChars, // < totalChars if the budget ran out
        full: final.matchedChars === word.length,
        encodedHex: ascii8hex(word),
        matchedNibbles: final.matchedChars * 2,
        nonce: final.nonce,
        attempts: final.nonce + 1,
        hash: final.hash,
        steps
      };
    }),
    words: ["use","utility","aura","price","worth"]
  };
})();
